import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"宣传口径与平台文案骨架","description":"","frontmatter":{},"headers":[],"relativePath":"modules/kits/promotion.md","filePath":"modules/kits/promotion.md","lastUpdated":0}`),a={name:`modules/kits/promotion.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="宣传口径与平台文案骨架" tabindex="-1">宣传口径与平台文案骨架 <a class="header-anchor" href="#宣传口径与平台文案骨架" aria-label="Permalink to “宣传口径与平台文案骨架”">​</a></h1><p>本页是对外发布文案的口径基准. 一切文案以<a href="./verification.html">验证状态</a>为前提: <strong>未实测项不得写成已验证</strong>. 下列骨架标注「待实测后定稿」, 实测通过后再定稿发布</p><h2 id="主口径-一个插件顶五个" tabindex="-1">主口径: 一个插件顶五个 <a class="header-anchor" href="#主口径-一个插件顶五个" aria-label="Permalink to “主口径: 一个插件顶五个”">​</a></h2><p>一套 EmakiKits 覆盖五类礼包需求, 不用再装对应的单功能插件:</p><table tabindex="0"><thead><tr><th>覆盖的需求</th><th>对应能力</th></tr></thead><tbody><tr><td>每日 / 每周 / 每月奖励</td><td><code>daily</code> / <code>weekly</code> / <code>monthly</code> 周期礼包</td></tr><tr><td>CDK 兑换</td><td><code>cdk</code> 礼包 (全服一次 / 每玩家计次)</td></tr><tr><td>新手礼包</td><td><code>join</code> 入服礼包 (含邀请码绑定)</td></tr><tr><td>自选礼包</td><td><code>choice</code> 礼包 (内联 GUI)</td></tr><tr><td>邀新礼包</td><td><code>invite</code> 礼包 + 邀请排行榜</td></tr></tbody></table><p>口径红线:</p><ul><li>签到玩法不在卖点内 (EmakiKits 明确不做签到, 见<a href="./scope.html">范围与边界</a>), 文案不得把签到列入</li><li>不写 &quot;独立可用 / 免前置 / 精简模式&quot;; 硬依赖 EmakiCoreLib 如实披露</li><li>未实测的能力写 &quot;待实测&quot;, 不写 &quot;已验证 / 稳定运行&quot;; &quot;未声明&quot; 不等于 &quot;没有&quot;, 反之 &quot;已实现&quot; 不等于 &quot;已实测&quot;</li></ul><h2 id="三平台文案骨架-待实测后定稿" tabindex="-1">三平台文案骨架 (待实测后定稿) <a class="header-anchor" href="#三平台文案骨架-待实测后定稿" aria-label="Permalink to “三平台文案骨架 (待实测后定稿)”">​</a></h2><h3 id="minebbs-中文" tabindex="-1">MineBBS (中文) <a class="header-anchor" href="#minebbs-中文" aria-label="Permalink to “MineBBS (中文)”">​</a></h3><ul><li>一句话: 配置驱动的礼包模块: 入服, 邀新, 每日, 每周, 每月, CDK, 自选与通用礼包都在一个插件里</li><li>要点: 一文件一礼包 YAML; 四类奖励 (物品 / 货币 / 嵌套礼包 / 动作管道); 幂等键 + 审计 + 原子写; 全 GUI 编辑器; 随机奖励保底; 邀请排行榜; Paper 26.1+ 与 Folia</li><li>依赖披露: 硬依赖 EmakiCoreLib (同一体系, 提供物品来源 / 动作管道 / GUI / 经济桥); 可选 PlaceholderAPI (占位符 <code>%emakikits_invited%</code>)</li><li>版本: 1.0.6</li></ul><h3 id="spigotmc-英文" tabindex="-1">SpigotMC (英文) <a class="header-anchor" href="#spigotmc-英文" aria-label="Permalink to “SpigotMC (英文)”">​</a></h3><ul><li>One line: A configuration-driven kit plugin: join, invite, daily, weekly, monthly, CDK, choice and generic kits in one place</li><li>Points: one kit per YAML file; four reward types (items, money, nested kits, CoreLib action lines); idempotent claims with audit records and atomic writes; in-game GUI editor; random-reward pity; invite leaderboard with PlaceholderAPI support</li><li>Dependency disclosure: requires EmakiCoreLib (same ecosystem); PlaceholderAPI optional</li><li>Format: 按发布渠道的 BBCode 要求转换, 事实与 MineBBS 条目一致</li></ul><h3 id="modrinth-markdown" tabindex="-1">Modrinth (Markdown) <a class="header-anchor" href="#modrinth-markdown" aria-label="Permalink to “Modrinth (Markdown)”">​</a></h3><ul><li>One line: 同 SpigotMC</li><li>Points: 同 SpigotMC, Markdown 列表</li><li>版本与兼容基线: 1.0.6, Paper 26.1+ (Folia supported); 实测状态引用<a href="./verification.html">验证状态</a>, 未实测不写</li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};